INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (354944, 15189, 'The Times of India', 'en', 'Bengal hotel fire: 7 charred to death in Birbhum, several critically injured', 'https://timesofindia.indiatimes.com/city/kolkata/tarapith-hotel-fire-5-guests-charred-to-death-several-critically-injured/articleshow/133285434.cms', 'A massive fire erupted at Hotel Bideshinii in Tarapith early Monday morning. Five guests were killed and several others critically injured in the devastating blaze. The fire quickly engulfed the hotel, trapping many guests who were asleep. Firefighters rushed to the scene and brought the flames under control. Injured individuals were transported to Rampurhat Government Medical College and Hospital.', 'https://static.toiimg.com/photo/msid-133285657,imgsize-255772.cms', '2026-08-17T02:59:06+00:00', '2026-08-17T03:32:31.106603'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
