INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (356929, 15191, 'South China Morning Post', 'en', '‘Heroes’ star Hayden Panettiere dies aged 36, father confirms', 'https://www.scmp.com/news/world/united-states-canada/article/3364248/heroes-star-hayden-panettiere-dies-aged-36-father-confirms', 'Hayden Panettiere, star of popular television series including Heroes and Nashville, has died. She was 36. Panettiere’s father, Skip, announced the actress’ death in a statement provided to ABC News on Sunday. “It is with profound sadness that we share the tragic passing of our beloved Hayden. She was an incredible light and a force of nature who brought immeasurable love and joy to all who knew her – and to the millions who watched her onscreen,” his statement said. No cause of death was...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/17/e31a88c5-a8ba-4690-97f9-4b5fd66bcaf0_a470b24d.jpg?itok=7aKVRHbH&v=1786943428', '2026-08-17T05:10:39+00:00', '2026-08-17T05:43:44.958064'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
